#!/usr/bin/env python3
"""Patch only notification delivery/settings in existing gardenApi and gardenPush.
Run without --deploy to prepare; --deploy updates both existing functions.
"""
BASELINE = '92b516fc3d9b518a2acdb28172e1654fa57d2c93cf2045c9d9d0c7f4b7eb1e22'
PAYLOAD = ''

import argparse,base64,hashlib,json,os,shutil,subprocess,tempfile,zipfile,shlex
from pathlib import Path
PROJECT='mycatapp-99bc8'
REGION='asia-northeast3'
FLAGS=['--project='+PROJECT,'--region='+REGION,'--gen2']
def run(args): return subprocess.check_output(args,text=True)
def describe(name): return json.loads(run(['gcloud','functions','describe',name,*FLAGS,'--format=json']))
def patch(root):
    p=root/'push-notifications.js';new=base64.b64decode(PAYLOAD)
    if not p.is_file(): raise RuntimeError('Notification module absent. Nothing changed.')
    if p.read_bytes()==new:return False
    if hashlib.sha256(p.read_bytes()).hexdigest()!=BASELINE:raise RuntimeError('Deployed notification module differs. Review before merging; nothing overwritten.')
    p.write_bytes(new);return True
def main():
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--deploy',action='store_true');ap.add_argument('--check-source',type=Path);args=ap.parse_args()
    if args.check_source:
        patch(args.check_source);print('Source patch verified.');return
    os.umask(0o077)
    for command in ['gcloud','node']:
        if not shutil.which(command):raise RuntimeError('Run in Google Cloud Shell: '+command+' is required.')
    work=Path(tempfile.mkdtemp(prefix='mindnyang-bell-v56-',dir=Path.home()));plans=[]
    for name in ['gardenApi','gardenPush']:
        meta=describe(name);build=meta.get('buildConfig',{});storage=build.get('source',{}).get('storageSource',{})
        if meta.get('environment')!='GEN_2' or build.get('entryPoint')!=name or build.get('runtime')!='nodejs22' or not storage.get('bucket') or not storage.get('object'):raise RuntimeError('Existing function identity is not recognized: '+name)
        uri='gs://'+storage['bucket']+'/'+storage['object']
        if storage.get('generation'):uri+='#'+str(storage['generation'])
        folder=work/name;folder.mkdir();archive=folder/'original.zip';source=folder/'original'
        subprocess.run(['gcloud','storage','cp',uri,str(archive),'--quiet'],check=True)
        with zipfile.ZipFile(archive) as z:
            for i in z.infolist():
                p=Path(i.filename)
                if p.is_absolute() or '..' in p.parts or (i.external_attr>>16)&0o170000==0o120000:raise RuntimeError('Unsafe source archive')
            z.extractall(source)
        roots=[p.parent for p in source.rglob('push-notifications.js') if (p.parent/'index.js').is_file() and (p.parent/'package.json').is_file()]
        if len(roots)!=1:raise RuntimeError('Cannot identify one backend source root for '+name)
        root=roots[0];patched=folder/'patched';shutil.copytree(root,patched);changed=patch(patched)
        subprocess.run(['node','--check',str(patched/'push-notifications.js')],check=True)
        deploy=['gcloud','functions','deploy',name,*FLAGS,'--source='+str(patched),'--quiet']
        rollback=[a if not a.startswith('--source=') else '--source='+str(root) for a in deploy]
        (folder/'ROLLBACK.txt').write_text(shlex.join(rollback)+'\n')
        plans.append((name,meta,deploy,changed))
    print('Both patches verified. Backups, source and rollback commands:',work)
    print('Only push-notifications.js changes. Existing triggers, secrets, environment, IAM and test access are retained.')
    if not args.deploy:print('Run this script with --deploy to apply both patches.');return
    # Preflight both again before the first write.
    for name,meta,_,_ in plans:
        if describe(name).get('updateTime')!=meta.get('updateTime'):raise RuntimeError('Function changed during preparation: '+name)
    for name,meta,deploy,changed in plans:
        if not changed:print(name+': already current');continue
        if describe(name).get('updateTime')!=meta.get('updateTime'):raise RuntimeError('Function changed before update: '+name)
        subprocess.run(deploy,check=True)
        after=describe(name)
        if after.get('state')!='ACTIVE':raise RuntimeError(name+' did not report ACTIVE. Inspect Cloud Console; backups retained.')
        beforeConfig=meta.get('serviceConfig',{});afterConfig=after.get('serviceConfig',{})
        for key in ['environmentVariables','secretEnvironmentVariables','secretVolumes','serviceAccountEmail']:
            if beforeConfig.get(key)!=afterConfig.get(key):raise RuntimeError(name+' configuration changed unexpectedly: '+key+'; inspect backups.')
        print(name+': ACTIVE')
    print('Both server functions updated. Open v56 app and sync notification settings, then test foreground/background sound and mute on a phone.')
if __name__=='__main__':
    try:main()
    except (RuntimeError,subprocess.CalledProcessError) as e:raise SystemExit('Stopped: '+str(e))
